// .cursor-plugin/plugin.json 예시
{
  "name": "continual-learning",
  "version": "1.0.0",
  "description": "Incremental transcript-driven memory updates"
}

server {
    listen 80;
    server_name example.com;
    location / {
        proxy_pass http://backend_cluster;
    }
}

// Example: Integrating Stitch Skill in Agent Context
import { StitchDesignSkill } from '@google-labs/stitch-skills';

const agentSkill = new StitchDesignSkill();
await agentSkill.execute({ theme: 'modern', target: 'react' });

// Example: Integrating Stitch Skill in Agent Context
import { StitchDesignSkill } from '@google-labs/stitch-skills';

const agentSkill = new StitchDesignSkill();
await agentSkill.execute({ theme: 'modern', target: 'react' });

import { AgAgentClient } from '@ag-ui/core';

const client = new AgAgentClient({ endpoint: '/api/agent' });
client.connect();

import { Button } from '@astryxdesign/core';

export default function App() {
  return <Button variant="primary">AI Ready Button</Button>;
}

import { Univer } from '@univerjs/core';

const univer = new Univer();
univer.createSheet({ name: 'My Sheet' });

# MCP 설정 내 ffmpeg-skill 등록
{
  "mcpServers": {
    "ffmpeg": {
      "command": "ffmpeg-skill"
    }
  }
}

/* Hallmark 테마 적용 예시 */
@import 'hallmark/themes/paper-v2.css';
body { data-hallmark-theme: 'editorial-raw'; }

// 에이전트 보안 감사 실행 설정 예시
import { runSecurityAudit } from '@cloudflare/security-audit-skill';

await runSecurityAudit({ targetPath: './src', phases: 'all' });

import { MausBotCore } from '@openmaus/core';

const bot = new MausBotCore({ model: 'claude-3-7', sandbox: 'local-vm' });
bot.listen();

